<div class="card mb-3"><div class="card-body"><h6>Tambah User</h6><form method="post" action="<?= base_url('super-admin/users/store') ?>" class="row g-2"><?= csrf_field() ?><div class="col-md-6"><input name="full_name" class="form-control" placeholder="Nama lengkap" required></div><div class="col-md-6"><input name="email" type="email" class="form-control" placeholder="Email" required></div><div class="col-md-4"><input name="username" class="form-control" placeholder="Username" required></div><div class="col-md-4"><input name="password" type="password" class="form-control" placeholder="Password" required></div><div class="col-md-4"><select name="user_level" id="userLevel" class="form-select" required><option value="">Pilih role</option><option value="super_admin">Super Admin</option><option value="admin">Admin</option><option value="kepala">Kepala</option><option value="gizi">Gizi</option><option value="keuangan">Keuangan</option><option value="aslap">Aslap</option><option value="koperasi">Koperasi</option></select></div><div class="col-md-6" id="sppgBox"><select name="id_sppg" class="form-select"><option value="">Pilih SPPG</option><?php foreach($sppgs as $s): ?><option value="<?= esc($s['id_sppg']) ?>"><?= esc($s['sppg_name']) ?> (<?= esc($s['id_sppg']) ?>)</option><?php endforeach; ?></select></div><div class="col-md-6" id="koperasiBox"><select name="koperasi_id" class="form-select"><option value="">Pilih Koperasi</option><?php foreach($koperasis as $k): ?><option value="<?= $k['id'] ?>"><?= esc($k['nama_koperasi']) ?></option><?php endforeach; ?></select></div><div class="col-12"><button class="btn btn-primary">Buat User</button></div></form></div></div>
