<?= $this->section('scripts') ?><script>const l=document.getElementById('userLevel'),s=document.getElementById('sppgBox'),k=document.getElementById('koperasiBox');function x(){let v=l.value;s.style.display=['kepala','gizi','keuangan','aslap'].includes(v)?'block':'none';k.style.display=v==='koperasi'?'block':'none'}l.addEventListener('change',x);x();</script><?= $this->endSection() ?>
